<template><main class="feedback-page"><el-card shadow="never"><div class="eyebrow">产品运营反馈</div><h1>告诉我们哪里需要改进</h1><p>问题会进入运营后台，由管理员分派、跟进并记录处理结果。</p><el-form label-position="top"><el-form-item label="问题类型"><el-select v-model="form.category" style="width:100%"><el-option label="功能问题" value="BUG"/><el-option label="使用建议" value="SUGGESTION"/><el-option label="数据或权限问题" value="DATA"/><el-option label="其他" value="OTHER"/></el-select></el-form-item><el-form-item label="标题"><el-input v-model="form.title" maxlength="120" show-word-limit /></el-form-item><el-form-item label="问题描述"><el-input v-model="form.content" type="textarea" :rows="8" maxlength="2000" show-word-limit placeholder="请描述复现步骤、期望结果和实际结果" /></el-form-item><div class="actions"><el-button @click="router.back()">取消</el-button><el-button type="primary" :loading="saving" @click="submit">提交反馈</el-button></div></el-form></el-card></main></template>
<script setup lang="ts">import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {submitFeedback} from '../services/feedbackApi';const router=useRouter();const saving=ref(false);const form=reactive({category:'BUG',title:'',content:''});async function submit(){if(!form.title.trim()||!form.content.trim()){ElMessage.warning('请填写标题和问题描述');return}saving.value=true;try{await submitFeedback(form);ElMessage.success('反馈已提交，运营人员会跟进处理');router.back()}catch(e){ElMessage.error(e instanceof Error?e.message:'反馈提交失败')}finally{saving.value=false}}</script>
<style scoped>.feedback-page{min-height:100%;padding:56px;background:#f7f9fc}.feedback-page .el-card{max-width:720px;margin:auto;border-radius:16px}.eyebrow{color:#4f6ef7;font-size:12px;font-weight:700;letter-spacing:.08em}.feedback-page h1{margin:10px 0 8px;color:#172b4d}.feedback-page p{margin:0 0 24px;color:#718096}.actions{display:flex;justify-content:flex-end;gap:10px}</style>
